-- MW4 Camo Tracker — partie administration
-- À exécuter UNE fois dans Supabase : SQL Editor > New query > coller > Run.
-- (Nécessite d'avoir déjà exécuté schema.sql.)

-- ============================================================
-- 1. Administrateurs
-- ============================================================
create table if not exists public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade
);
alter table public.admins enable row level security;

-- Chacun peut seulement vérifier s'il est lui-même admin. Aucune écriture possible depuis le site :
-- on ajoute un admin uniquement depuis le SQL Editor (voir tout en bas).
drop policy if exists "admins_select_self" on public.admins;
create policy "admins_select_self" on public.admins
  for select to authenticated
  using ((select auth.uid()) = user_id);

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.admins where user_id = (select auth.uid()));
$$;

-- ============================================================
-- 2. Catalogue des armes (lisible par tous, modifiable par les admins)
-- ============================================================
create table if not exists public.weapons (
  id                 text primary key,              -- identifiant stable (lié à la progression des joueurs)
  name               text not null,
  category           text not null,
  level              integer not null default 1,     -- niveau de déblocage
  season             integer not null default 0 check (season >= 0), -- 0 = arme de base, n = arrivée en Saison n
  image_url          text,                           -- null = image intégrée au site (/weapons/<id>.webp)
  multi              text[] not null default array[]::text[],   -- 7 défis : S1, S2, S3, Or, Platine, Rupture harmonique, Divergence
  dmz                text[] not null default array[]::text[],   -- idem pour DMZ
  warzone            text[] not null default array[]::text[],   -- 7 défis Warzone : S1, S2, S3, Golden Damascus, Starglass, Absolute Zero, Apocalypse
  prestige_available boolean[] not null default array[true, true, true, true]::boolean[], -- Prestige 1, P1 max, Niv. 150, Niv. 250
  mastery            boolean not null default false, -- compte pour le déblocage de la Divergence
  sort_order         integer not null default 0,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
alter table public.weapons enable row level security;

drop policy if exists "weapons_read_all" on public.weapons;
create policy "weapons_read_all" on public.weapons
  for select to anon, authenticated
  using (true);

drop policy if exists "weapons_admin_insert" on public.weapons;
create policy "weapons_admin_insert" on public.weapons
  for insert to authenticated
  with check ((select public.is_admin()));

drop policy if exists "weapons_admin_update" on public.weapons;
create policy "weapons_admin_update" on public.weapons
  for update to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

drop policy if exists "weapons_admin_delete" on public.weapons;
create policy "weapons_admin_delete" on public.weapons
  for delete to authenticated
  using ((select public.is_admin()));

-- ============================================================
-- 3. Images des armes (bucket public en lecture, upload réservé aux admins)
-- ============================================================
insert into storage.buckets (id, name, public)
values ('weapon-images', 'weapon-images', true)
on conflict (id) do update set public = true;

drop policy if exists "weapon_images_admin_insert" on storage.objects;
create policy "weapon_images_admin_insert" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'weapon-images' and (select public.is_admin()));

drop policy if exists "weapon_images_admin_update" on storage.objects;
create policy "weapon_images_admin_update" on storage.objects
  for update to authenticated
  using (bucket_id = 'weapon-images' and (select public.is_admin()));

drop policy if exists "weapon_images_admin_delete" on storage.objects;
create policy "weapon_images_admin_delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'weapon-images' and (select public.is_admin()));

